(376415, 30912, 9027, '<td valign="top">whoah, now there''s a image for nightmares. great drama and love the noir-esque shadows.</td>', 'whoah, now there''s a image for nightmares. great drama and love the noir-esque shadows.', '2003-08-04 14:47:18.000000', NULL, 1),
(376418, 31768, 9027, '<td valign="top">nice shot. love the foreboding silohuetted killer, as well as the very soft tones created in the shower curtain. the only thing i would change is where the hand aligns with the shower rod. i wish they didn''t. :o)</td>', 'nice shot. love the foreboding silohuetted killer, as well as the very soft tones created in the shower curtain. the only thing i would change is where the hand aligns with the shower rod. i wish they didn''t. :o)', '2003-08-04 14:50:22.000000', NULL, 1),
