INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(376442, 31811, 3018, '<td valign="top">Very dark concept, but this is a creative way of representing this movie.  Good job!</td>', 'Very dark concept, but this is a creative way of representing this movie.  Good job!', '2003-08-04 15:22:08.000000', NULL, 1),
(376444, 31799, 9452, '<td valign="top">LOL</td>', 'LOL', '2003-08-04 15:23:29.000000', NULL, 1),
(376447, 31813, 3018, '<td valign="top">Wow! Great movie! You did a very good job of representing it.  Nice composition, and you even got the right porcelain.  Cool!  Lighting could be better, as it seems a little dark.  Colors need to be more alive. Good luck!</td>', 'Wow! Great movie! You did a very good job of representing it.  Nice composition, and you even got the right porcelain.  Cool!  Lighting could be better, as it seems a little dark.  Colors need to be more alive. Good luck!', '2003-08-04 15:24:35.000000', NULL, 1),
(376450, 31774, 9452, '<td valign="top">Well done, i hate this movie, but you did it real good :) 9</td>', 'Well done, i hate this movie, but you did it real good :) 9', '2003-08-04 15:28:58.000000', NULL, 1),
(376455, 31811, 9452, '<td valign="top">Good composition, sepia color really works for this one.</td>', 'Good composition, sepia color really works for this one.', '2003-08-04 15:30:36.000000', NULL, 1),
(376459, 31850, 9452, '<td valign="top">Too dark for me</td>', 'Too dark for me', '2003-08-04 15:34:07.000000', NULL, 1),
(376462, 31857, 9452, '<td valign="top">I would prefered for this one \"Le cage aux follies\" or \"The bird´s Cage\"</td>', 'I would prefered for this one \"Le cage aux follies\" or \"The bird´s Cage\"', '2003-08-04 15:38:13.000000', NULL, 1),
(376470, 31776, 10250, '<td valign="top">I had actually considered a shot similar to this. Memento is a great movie. If I remember correctly, it was Sammy Jenkins, but wouldn''t it be ironic if I couldn''t remember? 9</td>', 'I had actually considered a shot similar to this. Memento is a great movie. If I remember correctly, it was Sammy Jenkins, but wouldn''t it be ironic if I couldn''t remember? 9', '2003-08-04 15:50:40.000000', NULL, 1),
(376471, 31858, 6388, '<td valign="top">Awesome job.   ''cept the little girl is looking a little more masculine than i remember.  :)   one of my top votes so far.  I like the thin white line inside your border, sets it off nicely.  Pedro</td>', 'Awesome job.   ''cept the little girl is looking a little more masculine than i remember.  :)   one of my top votes so far.  I like the thin white line inside your border, sets it off nicely.  Pedro', '2003-08-04 15:50:44.000000', NULL, 1),
(376473, 31768, 10250, '<td valign="top">There are several shots that depict this scene, but this one I think is the better of them. 7</td>', 'There are several shots that depict this scene, but this one I think is the better of them. 7', '2003-08-04 15:52:57.000000', NULL, 1),
(376474, 31811, 10250, '<td valign="top">Dismemebered baby. It''s the breakfast of champions. 8.</td>', 'Dismemebered baby. It''s the breakfast of champions. 8.', '2003-08-04 15:53:44.000000', NULL, 1),
(376475, 31840, 6388, '<td valign="top">This actually looks more like part III to me, he''s not showing enough character development for part VI.  I''m kidding. great shot - like the backlighting and the setting.  Good thought shooting it from below - adds nice perspective.</td>', 'This actually looks more like part III to me, he''s not showing enough character development for part VI.  I''m kidding. great shot - like the backlighting and the setting.  Good thought shooting it from below - adds nice perspective.', '2003-08-04 15:54:36.000000', NULL, 1),
(376477, 31554, 6388, '<td valign="top">pesky shadow on the right of Spidey''s head.  I''d have bounced a little light behind him from the other side to get rid of it.  nice pic though - interesting DOF on the hand.</td>', 'pesky shadow on the right of Spidey''s head.  I''d have bounced a little light behind him from the other side to get rid of it.  nice pic though - interesting DOF on the hand.', '2003-08-04 15:56:20.000000', NULL, 1),
(376478, 31789, 10250, '<td valign="top">The image here shows a good bit of jpeg compression. I''d like to see the original. 7.</td>', 'The image here shows a good bit of jpeg compression. I''d like to see the original. 7.', '2003-08-04 15:56:53.000000', NULL, 1),
(376481, 31857, 6388, '<td valign="top">hilarious.   a little disturbing, but hilarious.  New York?  I think you should have used this for self-portrait.</td>', 'hilarious.   a little disturbing, but hilarious.  New York?  I think you should have used this for self-portrait.', '2003-08-04 15:58:08.000000', NULL, 1),
(376482, 31545, 10250, '<td valign="top">I like the shot, and the color is excellent, but I would have liked to see the swans larger. 6.</td>', 'I like the shot, and the color is excellent, but I would have liked to see the swans larger. 6.', '2003-08-04 15:58:17.000000', NULL, 1),
(376483, 31769, 10250, '<td valign="top">I like the composition, but I think the image is too low in contrast,  and the wash out in the stump, and behind the trees are distracting. 5.</td>', 'I like the composition, but I think the image is too low in contrast,  and the wash out in the stump, and behind the trees are distracting. 5.', '2003-08-04 16:00:18.000000', NULL, 1),
(376484, 31769, 6388, '<td valign="top">Jed...?  s''at you...?  Who''s playin'' that Gee-tar?  Nice composition, good crop.  too hot on top - trees blow out a bit, which I''m ok with if it adds to the image, but it doesn''t this time.  Metering to the trees and using a fill-flash would have helped in my books.</td>', 'Jed...?  s''at you...?  Who''s playin'' that Gee-tar?  Nice composition, good crop.  too hot on top - trees blow out a bit, which I''m ok with if it adds to the image, but it doesn''t this time.  Metering to the trees and using a fill-flash would have helped in my books.', '2003-08-04 16:00:27.000000', NULL, 1),
(376485, 31811, 2716, '<td valign="top">lol.  This is so sick that it works.  Great tones and very gruesome.  Great shot.  Jacko.  9</td>', 'lol.  This is so sick that it works.  Great tones and very gruesome.  Great shot.  Jacko.  9', '2003-08-04 16:01:30.000000', NULL, 1),
(376486, 31621, 2716, '<td valign="top">Wonderfull color and feel to this picture.   Great facial expression. Great shot.   Jacko.  9</td>', 'Wonderfull color and feel to this picture.   Great facial expression. Great shot.   Jacko.  9', '2003-08-04 16:03:23.000000', NULL, 1),
(376488, 31853, 10250, '<td valign="top">I like the image. I think it would have been more effective taken at night, with a carefully placed flash and the white balance set for tungsten lighting. Often times in movies, they exploit the contrast of orange and blue lighting, and that would have given the image more of that feel. 6.</td>', 'I like the image. I think it would have been more effective taken at night, with a carefully placed flash and the white balance set for tungsten lighting. Often times in movies, they exploit the contrast of orange and blue lighting, and that would have given the image more of that feel. 6.', '2003-08-04 16:05:53.000000', NULL, 1),
(376489, 31660, 2612, '<td valign="top">Nice image, but it looks like the cat moved and caused some out of focus.</td>', 'Nice image, but it looks like the cat moved and caused some out of focus.', '2003-08-04 16:07:45.000000', NULL, 1),
(376492, 31768, 10263, '<td valign="top">Excellent! A for sure winner</td>', 'Excellent! A for sure winner', '2003-08-04 16:09:23.000000', NULL, 1),
