(377624, 31670, 778, '<td valign="top">Love the composition and colors.  Gets an 8 from me...just one note...I live in Kansas and I would love to know where that mountain is so I can go there! :)</td>', 'Love the composition and colors.  Gets an 8 from me...just one note...I live in Kansas and I would love to know where that mountain is so I can go there! :)', '2003-08-05 20:42:55.000000', NULL, 1),
(377627, 31525, 10541, '<td valign="top">Pretty good - and original presentation - took me a whie to realise that the vertical "line" was a knife. Reminds me of the method to be used when viewing cloudscapes pics in 3D.</td>', 'Pretty good - and original presentation - took me a whie to realise that the vertical "line" was a knife. Reminds me of the method to be used when viewing cloudscapes pics in 3D.', '2003-08-05 20:47:56.000000', NULL, 1),
