(377634, 31799, 10541, '<td valign="top">Much better than the too-literal interpretations or this challenge - made me smile</td>', 'Much better than the too-literal interpretations or this challenge - made me smile', '2003-08-05 20:53:13.000000', NULL, 1),
(377635, 31621, 10541, '<td valign="top">Stunning image - the girl looks totally mesmorized - the exposure must have been difficult. The framing is spot on. Would get my 10 if I could vote, although "Blade Runner" would get a 9 for originality.</td>', 'Stunning image - the girl looks totally mesmorized - the exposure must have been difficult. The framing is spot on. Would get my 10 if I could vote, although "Blade Runner" would get a 9 for originality.', '2003-08-05 20:55:27.000000', NULL, 1),
