(380358, 31174, 6870, '<td valign="top">Feed me Seymour! Nice dramatic capture and great composition.</td>', 'Feed me Seymour! Nice dramatic capture and great composition.', '2003-08-07 11:20:09.000000', NULL, 1),
(380366, 31804, 6870, '<td valign="top">Here''s some drama! I like the expression The lighting is a bit harsh here, and colors nonsaturated, as I find in some of your other shots. I''m not sure what camera you have, but I would really experiment with light and slightly different colors and qualities and directions of light and rely less on your flash. It tends to wash things out and give a harsh feel to things. Your composition is really nice here, and the point of view is just right, but your lighting upstages most of this wonderful work.</td>', 'Here''s some drama! I like the expression The lighting is a bit harsh here, and colors nonsaturated, as I find in some of your other shots. I''m not sure what camera you have, but I would really experiment with light and slightly different colors and qualities and directions of light and rely less on your flash. It tends to wash things out and give a harsh feel to things. Your composition is really nice here, and the point of view is just right, but your lighting upstages most of this wonderful work.', '2003-08-07 11:24:30.000000', NULL, 1),
(380368, 31605, 6870, '<td valign="top">Cute pup. I wish he were more in focus. I love the expression, and I really enjoy the colors in this shot.</td>', 'Cute pup. I wish he were more in focus. I love the expression, and I really enjoy the colors in this shot.', '2003-08-07 11:25:21.000000', NULL, 1),
(380369, 31811, 6870, '<td valign="top">Pretty silly! I love it.</td>', 'Pretty silly! I love it.', '2003-08-07 11:26:04.000000', NULL, 1),
(380372, 31854, 6870, '<td valign="top">The over-contrast gives this an old photo feel that I like. Wish you were closer to the guys, though.</td>', 'The over-contrast gives this an old photo feel that I like. Wish you were closer to the guys, though.', '2003-08-07 11:27:05.000000', NULL, 1),
(380374, 31787, 6870, '<td valign="top">Is this Larry himself? Nice point of view and expression on the camel. Light seems a bit harsh, especially on the face and head.</td>', 'Is this Larry himself? Nice point of view and expression on the camel. Light seems a bit harsh, especially on the face and head.', '2003-08-07 11:28:53.000000', NULL, 1),
(380375, 31551, 6870, '<td valign="top">Perfect. tones, idea, execution, lighting. Everything. 10</td>', 'Perfect. tones, idea, execution, lighting. Everything. 10', '2003-08-07 11:29:30.000000', NULL, 1),
(380377, 30912, 6870, '<td valign="top">Yow! I do NOT want to see this movie! Nice horror feel!</td>', 'Yow! I do NOT want to see this movie! Nice horror feel!', '2003-08-07 11:30:04.000000', NULL, 1),
(380381, 31799, 6870, '<td valign="top">Tones, lighting are just right for this film, but I have to ask: What is a silver paper unicorn doing in one of the most interesting and bizarre films ever made?</td>', 'Tones, lighting are just right for this film, but I have to ask: What is a silver paper unicorn doing in one of the most interesting and bizarre films ever made?', '2003-08-07 11:31:55.000000', NULL, 1),
(380383, 31824, 6870, '<td valign="top">Look! A pushme-pullyou! A cute one, too. Nice point of view and lighting is nice without being harsh.</td>', 'Look! A pushme-pullyou! A cute one, too. Nice point of view and lighting is nice without being harsh.', '2003-08-07 11:32:48.000000', NULL, 1);
