(380835, 31836, 7033, '<td valign="top">Very nicely done!  Probably my favorite here so far.  I especially like the subdued tones and desaturated colors-- it sets the mood nicely.</td>', 'Very nicely done!  Probably my favorite here so far.  I especially like the subdued tones and desaturated colors-- it sets the mood nicely.', '2003-08-07 15:49:25.000000', NULL, 1),
(380839, 31786, 7033, '<td valign="top">Beautiful B/W shot with a nice range of tones, and good contrast.  Only distraction in the shot is the bright bit of sky at the top left of the frame, but otherwise, very nicely done.  The connection to the movie is a bit tenuous, however.  --8</td>', 'Beautiful B/W shot with a nice range of tones, and good contrast.  Only distraction in the shot is the bright bit of sky at the top left of the frame, but otherwise, very nicely done.  The connection to the movie is a bit tenuous, however.  --8', '2003-08-07 15:51:26.000000', NULL, 1),
(380841, 31551, 2752, '<td valign="top">I like your choice..setting is good as is the costuming and props..your facial expression is right on.  Only downside would be that the shoe is too intact and hard to see.  Gave you a (9)</td>', 'I like your choice..setting is good as is the costuming and props..your facial expression is right on.  Only downside would be that the shoe is too intact and hard to see.  Gave you a (9)', '2003-08-07 15:52:30.000000', NULL, 1),
(380843, 31767, 7033, '<td valign="top">I''ve never seen the movie so I can''t judge it on that aspect, but I like the composition and richly saturated color.  Quite nicely done!</td>', 'I''ve never seen the movie so I can''t judge it on that aspect, but I like the composition and richly saturated color.  Quite nicely done!', '2003-08-07 15:53:23.000000', NULL, 1),
