(383719, 31858, 9893, '<td valign="top">Great rendition of one of my all-time fave movies =)</td>', 'Great rendition of one of my all-time fave movies =)', '2003-08-11 02:08:43.000000', NULL, 0),
(383724, 31551, 1031, '<td valign="top">My mom not only knew Chaplin, she actually met the confectioner who made the boots they used (made of licorice) for this scene. Apparently they had a "bake-off" among some 25 local candy makers, and this guy got the contract. If you''re interested, you can check out some of the results of her second (more successful) go-round in Hollywoodland at <a href="//www.superloopers.com" rel="nofollow" target="_blank">SuperLoopers.com</a>. I have a more recent resume for her, but haven''t uploaded it yet.<br/> <br/>Excellent job capturing the look and feel of the movie!</td>', 'My mom not only knew Chaplin, she actually met the confectioner who made the boots they used (made of licorice) for this scene. Apparently they had a "bake-off" among some 25 local candy makers, and this guy got the contract. If you''re interested, you can check out some of the results of her second (more successful) go-round in Hollywoodland at SuperLoopers.com. I have a more recent resume for her, but haven''t uploaded it yet. Excellent job capturing the look and feel of the movie!', '2003-08-11 02:18:44.000000', NULL, 0),
